/*
Day #26/24: Eliptic
https://openprocessing.org/sketch/2410368
https://mathober.com/
https://openprocessing.org/curation/87980
*/

let S, N, FCD, ellipses;

function setup() {
  createCanvas(windowWidth, windowHeight);
	background(2, 2, 8);
	describe("different ellipses in cyan to purple growing, moving our from the center and rotating by each offsetting from the own center");
	frameRate(60);

  noFill();
	S = max(width, height);
	N = ~~random(3, 11);
	FCD = ~~random(100, 500);

	ellipses = [];
	addEllipse();
  loop();
}

function addEllipse() {
	const x = width/2;
	const y = height/2;
	const w = random(25, 150);
	const h = random(25, 150);
	const tx = random(w);
	const ty = random(h);
	const a = random(TWO_PI);
	const r = 0;
	const ea = random(TWO_PI);
	const ead = random(-0.1, 0.1);
	const clr = lerpColor(color("cyan"), color("purple"), random());
	const lt = random(0.75, 2);
	ellipses.push({x, y, w, h, tx, ty, a, r, ea, ead, clr, lt});
}

function draw() {
	if (frameCount%30 === 0) addEllipse();
	ellipses = ellipses.filter((e) => e.lt > 0);
	background(2, 2, 8, 48);
	translate(width/2, height/2)
	// rotate(noisom(1, 1.4, FCD)-1.2); // to avoid symmetries in nosir, instaed of (-0.2, 0.2)

	strokeWeight(3);
	for (let e of ellipses) drawEllipse(e);
}

function drawEllipse(e) {
	push();
	// {x, y, w, h, tx, ty, a, r, ea, ead, clr, lt}
	var x = cos(e.a) * e.r;
	var y = sin(e.a) * e.r;
	e.r+=0.25;


	noFill();
	var clr = e.clr;
	clr.setAlpha(e.lt*255)
	e.lt -= 0.005;
	stroke(clr);
	translate(e.tx, e.ty);
	rotate(e.ea)
	e.ea += e.ead;
	ellipse(x, y, e.w, e.h)
	e.w += 2
	e.h += 2

	pop();

	// console.log(e)
}


function noisom(v1, v2, fcd = 234) {
	if (v1>v2) [v1, v2] = [v2, v1];
	const n = noise(v1, v2, frameCount/234);
	return v1+n*(v2-v1);
}

function mouseClicked() {
  if (mouseButton === LEFT) setup();
}
